sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var INTERNAL_TOKEN = 'Banco do Nordeste';

    function normalize(s) {
        return (s || '').toString().replace(/\s+/g, ' ').trim();
    }

    // Root issuer (display ou value)
    var rootIssuer = normalize(current.getDisplayValue('root_issuer') || current.getValue('root_issuer'));

    // Se não tiver root_issuer, não faz nada (ou, se preferir, você pode forçar external aqui)
    if (!rootIssuer)
        return;

    var desired = (rootIssuer.toLowerCase().indexOf(INTERNAL_TOKEN.toLowerCase()) > -1)
        ? 'internal'
        : 'external';

    // ===== CONDITION "dentro" do script =====
    // Roda no INSERT sempre.
    // No UPDATE, só roda se root_issuer mudou OU se os campos estão diferentes do desejado.
    var shouldRun =
        current.operation() === 'insert' ||
        (current.isValidField('root_issuer') && current.root_issuer.changes()) ||
        (current.isValidField('u_ca_scope') && (current.getValue('u_ca_scope') || '') !== desired) ||
        (current.isValidField('service_type') && (current.getValue('service_type') || '') !== desired);

    if (!shouldRun)
        return;

    // Atualiza somente se precisar (evita update “à toa”)
    if (current.isValidField('u_ca_scope') && (current.getValue('u_ca_scope') || '') !== desired)
        current.setValue('u_ca_scope', desired);

    if (current.isValidField('service_type') && (current.getValue('service_type') || '') !== desired)
        current.setValue('service_type', desired);

})(current, previous);
